import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        long K = Long.parseLong(st.nextToken());

        if (K >= N) {
            System.out.println(0);
            return;
        }
        int C = (int) (N - K);

        long[] factorials = new long[200001];
        factorials[0] = 1;
        for (int i = 1; i <= 200000; i++) {
            factorials[i] = (factorials[i - 1] * i) % 998244353L;
        }

        long total = 0;
        int sign = 1;
        for (int i = C; i > 0; i--) {
            long val = (choose(C, i, factorials) * power(i, N, 998244353L)) % 998244353L;
            total = (total + sign * val + 998244353L * 2) % 998244353L;
            sign *= -1;
        }

        long multiplier = 2 * choose(N, C, factorials);
        if (C == N)
            multiplier = 1L;
        System.out.println((total * multiplier) % 998244353L);
    }

    public static long choose(int n, int k, long[] fact) {
        long denom = (fact[k] * fact[n - k]) % 998244353L;
        long denomInv = power(denom, 998244353L - 2, 998244353L);
        return (fact[n] * denomInv) % 998244353L;
    }

    public static long power(long base, int exp, long mod) {
        long res = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
